// lib-config (N8N-2.6 seed): data only, no side effects. Temporary entries
// name the ticket they wait on.
const envLevel = String($env.WAZUH_ALERT_MIN_LEVEL ?? '').trim();
const envOk = /^\d+$/.test(envLevel);
// TheHive deployed for this core? THEHIVE_ENABLED is rendered by render-env.sh
// (R-18): false only on a machine without the cases node. Unset = enabled,
// which keeps the behaviour of machines rendered before the flag existed.
const thEnv = String($env.THEHIVE_ENABLED ?? '').trim().toLowerCase();
return [{ json: {
  config_version: '2026-09-30',
  // C1 threshold: WAZUH_ALERT_MIN_LEVEL from n8n's environment; 7 only as a fallback.
  min_level: envOk ? Number(envLevel) : 7,
  min_level_source: envOk ? 'env WAZUH_ALERT_MIN_LEVEL' : 'fallback',
  // "Not deployed here" (skip, no park) vs "deployed but down" (retry, park).
  thehive: {
    enabled: thEnv !== 'false',
    enabled_source: thEnv === '' ? 'default (THEHIVE_ENABLED unset)' : 'env THEHIVE_ENABLED',
  },
  // ALERT-FORMAT §2: rule.level -> TheHive severity (1 Low .. 4 Critical).
  severity_by_level: [
    { min: 12, max: 15, severity: 4 },
    { min: 10, max: 11, severity: 3 },
    { min: 7, max: 9, severity: 2 },
  ],
  severity_default: 1,
  // +1 (max 4) when asset-criticality is one of these (ALERT-FORMAT §2).
  severity_raise_for_criticality: ['high', 'critical'],
  asset_criticality: 'medium', // until an asset inventory exists
  tlp: 2,
  pap: 2,
  thehive_alert_type: 'wazuh',
  source_default: 'wazuh',
  // Test rules: their alerts get source asox-test (ALERT-FORMAT §1, R6).
  source_by_rule_id: { '100100': 'asox-test' },
  // ALERT-FORMAT §3, first match wins. A template matches when any clause
  // matches; a clause needs all of `all`, one of `any`, and a technique
  // starting with `mitre_prefix`, for the keys it has.
  case_templates: [
    { name: 'ssh-bruteforce', match: [
      { all: ['sshd'], any: ['authentication_failures', 'authentication_failed', 'invalid_login'] },
      { mitre_prefix: 'T1110' },
    ] },
    { name: 'malware-detection', match: [{ any: ['virustotal', 'rootcheck', 'yara', 'clamd', 'malware'] }] },
    { name: 'ids-network-alert', match: [{ any: ['suricata', 'ids'] }] },
    { name: 'wazuh-generic', default: true },
  ],
  // Observable dataTypes n8n sends (ALERT-FORMAT §5). An unknown type makes
  // TheHive refuse the whole alert (HTTP 404), so only loaded types are on.
  observable_types: {
    ip: true, hostname: true, hash: true, filename: true, url: true, fqdn: true,
    'user-account': false, // TEMPORARY: waits for T1.3 (TheHive entities/ on the build instance)
  },
  // Alerts matching these never reach a playbook; recv-wazuh-alert records them.
  intake_exclusions: [
    { rule_group: 'sca', label: 'sca (X-09)', temporary: true,
      ticket: 'X-09', note: 'TEMPORARY: SCA start-up burst; waits for the X-09 decision with Wazuh' },
  ],
  // lib-thehive-writeback: first line of the comment, and the author it must have.
  writeback: { marker: '[asox-n8n writeback]', author: 'n8n@asox.local' },
  error_marker: '[asox-n8n error]',
} }];
